_CACHE: dict[str, list[tuple[str, str]]] = {}


def _phrases(code: str) -> list[tuple[str, str]]:
    if code not in _CACHE:
        found = {said if code == "zh" else plain(said): english for english, words in HEARD[code].items() for said in words.split("|")}
        _CACHE[code] = sorted(found.items(), key=lambda kv: -len(kv[0]))
    return _CACHE[code]


def as_english(text: str, code: str) -> str:
    """``text`` said in language ``code``, with what the cabin crew knows of it in the English their script reads."""
    if code not in HEARD or not text.strip():
        return text
    if code == "zh":
        said = re.sub(r"[，。！？、]+", " ", text)
        for words, english in _phrases(code):
            said = said.replace(words, f" {english} ")
        return " ".join(said.split())
    said = f" {' '.join(plain(text).replace('.', ' ').replace(',', ' ').split())} "
    for words, english in _phrases(code):
        said = said.replace(f" {words} ", f" {english} ")
    return " ".join(said.split())


def drink_said(drink: str, code: str) -> str:
    """"coffee, black one sugar" as it's said in language ``code``."""
    table = DRINKS.get(code)
    if not table:
        return drink
    for english in sorted(table, key=len, reverse=True):
        drink = drink.replace(english, table[english])
    return drink
